// Generated by Suite Builder from a crawl of the site. The harness tests itself: checks and actions, on a page of its own.
// EDIT RULES: OFF LIMITS, to people and AIs alike. This file is one of the suite's rules (SUITE-RULES.md). A change to it, a move, a rename or a deletion is a change outside a YOURS block: regenerating will overwrite it, SR-16 reports it and suite verify finds it. To get a test through, fix the test or push back on the story; to change a rule, change Suite Builder.
import { Checks } from '../support/core/Checks';
import { Headings } from '../support/core/Headings';
import { byCss, elements } from '../support/core/PageElement';
import { StepLog } from '../support/core/StepLog';
import { UserActions } from '../support/core/UserActions';

/**
 * The suite tests the site; this tests the suite. A few seconds, on a page it writes itself (served
 * by cy.intercept: nothing of the site's), with every run:
 *
 * - every check passes what it should, and fails what it should with exactly the message a person
 *   will read in a real failure;
 * - every action does what its step says, and the step log says it.
 *
 * When one of these fails, the harness is broken, not the site: every other failure in the run is
 * suspect until it is fixed. Rebuilding the suite puts the harness back as generated.
 */
const PAGE = `<!DOCTYPE html>
<html><head><title>Harness page</title><style>html { scroll-behavior: smooth; }</style></head><body>
<h1>Harness <span>page</span></h1>
<h2>Contact&nbsp;<strong>Us</strong></h2>
<button id="add">Add one</button>
<button id="hidden" style="display:none">Hidden</button>
<button id="later">Later</button>
<button id="summon">Summon banner</button>
<button id="under">Under the banner</button>
<p id="under-clicked"></p>
<button class="twin">Twin</button><button class="twin">Twin</button>
<p id="count">0</p>
<p id="spaced">  Hello
     world  </p>
<label>Name <input id="name"></label>
<form action="/never"><label>Town <input id="town" required></label></form>
<label><input type="checkbox" id="agree"> I agree</label>
<select id="colour"><option>Red</option><option value="b">Blue</option></select>
<p id="late"></p>
<p id="quoted">Say "hi"</p>
<button id="off" disabled>Off</button>
<a id="help" href="/help">Help</a>
<ul id="items"><li>One</li><li>Two</li><li style="display:none">Three</li></ul>
<img src="https://harness.invalid/harness-missing.png" alt="">
<div style="height: 2400px"></div>
<button id="far">Far down</button>
<p id="far-clicked"></p>
<h2 id="reveal" style="opacity: 0; transition: opacity 0.2s">Revealed on scroll</h2>
<div style="height: 1200px"></div>
<script>
  document.getElementById('add').onclick = () => {
    const count = document.getElementById('count');
    count.textContent = String(Number(count.textContent) + 1);
  };
  document.getElementById('later').onclick = () =>
    setTimeout(() => { document.getElementById('late').textContent = 'Arrived'; }, 200);
  // A cookie banner that comes after the page opened, over everything (atos.net's, behind a slow page, 2026-10-06).
  document.getElementById('summon').onclick = () => {
    const banner = document.createElement('div');
    banner.style.cssText = 'position:fixed;inset:0;z-index:1000;background:rgba(0,0,0,0.3)';
    banner.innerHTML = '<button id="onetrust-accept-btn-handler">Accept all</button>';
    banner.querySelector('button').onclick = () => banner.remove();
    document.body.appendChild(banner);
  };
  document.getElementById('under').onclick = () => { document.getElementById('under-clicked').textContent = 'Clicked'; };
  document.getElementById('far').onclick = () => { document.getElementById('far-clicked').textContent = 'Clicked'; };
  // A section that fades in once it is scrolled to, as many sites draw theirs (Site G, 2026-10-03).
  new IntersectionObserver((seen) => seen.forEach((e) => { if (e.isIntersecting) e.target.style.opacity = '1'; })).observe(document.getElementById('reveal'));
  console.error('harness: a console error');
</script>
</body></html>`;

/** The harness page's elements, declared the way every page's Elements are. */
const Harness = elements({
  ADD_BUTTON: byCss('#add'),
  HIDDEN_BUTTON: byCss('#hidden'),
  LATER_BUTTON: byCss('#later'),
  COUNT: byCss('#count'),
  SPACED_TEXT: byCss('#spaced'),
  NAME_FIELD: byCss('#name'),
  TOWN_FIELD: byCss('#town'),
  AGREE_BOX: byCss('#agree'),
  COLOUR_LIST: byCss('#colour'),
  LATE_TEXT: byCss('#late'),
  OFF_BUTTON: byCss('#off'),
  HELP_LINK: byCss('#help'),
  FAR_BUTTON: byCss('#far'),
  SUMMON_BUTTON: byCss('#summon'),
  UNDER_BUTTON: byCss('#under'),
  UNDER_TEXT: byCss('#under-clicked'),
  FAR_TEXT: byCss('#far-clicked'),
  REVEALED_HEADING: byCss('#reveal'),
  CONTACT_HEADING: Headings.named('Contact Us'),
  MISSING_HEADING: Headings.named('Nowhere'),
});

/** The check that follows fails, saying exactly this; if it passes, the harness is broken. */
function says(message: string): void {
  cy.on('fail', (error) => {
    if (!error.message.includes(message)) throw error;
    return false;
  });
}

function failedToFail(): void {
  cy.then(() => {
    throw new Error('The check passed, and it should have failed.');
  });
}

describe('HarnessTest: the harness tests itself, on a page of its own', () => {
  beforeEach(() => {
    cy.intercept('GET', '**/__suite-builder-harness__', { statusCode: 200, headers: { 'content-type': 'text/html' }, body: PAGE });
    cy.intercept('GET', '**/harness-missing.png', { statusCode: 404, body: '' });
    cy.visit('/__suite-builder-harness__');
    // Checks made to fail fail in half a second, not ten (for this test only: Cypress puts it back).
    Cypress.config('defaultCommandTimeout', 500);
  });

  it('Checks pass what they should', () => {
    Checks.assume(true, 'never said'); // what the test needs is there: no step, and the test goes on
    Checks.isShown(Harness.ADD_BUTTON);
    Checks.isNotShown(Harness.HIDDEN_BUTTON);
    Checks.hasText(Harness.SPACED_TEXT, 'Hello world');
    Checks.containsText(Harness.SPACED_TEXT, 'world');
    Checks.pageShowsText('Add one');
    Checks.titleIs('Harness page');
    Checks.allShown('its buttons and headings', Harness.ADD_BUTTON, Harness.CONTACT_HEADING);
    UserActions.click(Harness.LATER_BUTTON);
    Cypress.config('defaultCommandTimeout', 4000);
    Checks.hasText(Harness.LATE_TEXT, 'Arrived'); // appears 0.2 s after the click: the check waits for it
    cy.then(() => expect(StepLog.steps(), 'Every check and action should log one step').to.have.length(9));
  });

  it('A heading split across elements, with a non-breaking space, is found by its words', () => {
    Checks.isShown(Harness.CONTACT_HEADING);
  });

  it('A click on something never shown says why', () => {
    says('the hidden button was not shown within 0.5 s: it is not on the page, or only where a visitor cannot see it (a closed menu, another slide, a layout for another screen size)');
    UserActions.click(Harness.HIDDEN_BUTTON);
    failedToFail();
  });

  it('isShown fails on a hidden element, saying so', () => {
    says('Expected the hidden button to be shown, but it was not (waited 0.5 s).');
    Checks.isShown(Harness.HIDDEN_BUTTON);
    failedToFail();
  });

  it('isNotShown fails on a shown element, saying so', () => {
    says('Expected the add button not to be shown, but it still was (waited 0.5 s).');
    Checks.isNotShown(Harness.ADD_BUTTON);
    failedToFail();
  });

  it('hasText fails on other text, quoting what it found', () => {
    says('Expected the spaced text to say "Goodbye", but it said "Hello world" (waited 0.5 s).');
    Checks.hasText(Harness.SPACED_TEXT, 'Goodbye');
    failedToFail();
  });

  it('hasText fails on a hidden element, saying it was not shown', () => {
    says('Expected the hidden button to say "Hidden", but it said nothing (it was not shown) (waited 0.5 s).');
    Checks.hasText(Harness.HIDDEN_BUTTON, 'Hidden');
    failedToFail();
  });

  it('containsText fails when the words are missing', () => {
    says('Expected the spaced text to mention "Goodbye", but it said "Hello world" (waited 0.5 s).');
    Checks.containsText(Harness.SPACED_TEXT, 'Goodbye');
    failedToFail();
  });

  it('hasValue fails on an empty field', () => {
    says('Expected the name field to hold "Ann", but it held "" (waited 0.5 s).');
    Checks.hasValue(Harness.NAME_FIELD, 'Ann');
    failedToFail();
  });

  it('refusesEmpty fails on a field the browser would send empty, saying why', () => {
    says('Expected the form not to be sent with the name field empty, but it is not required (waited 0.5 s).');
    Checks.refusesEmpty(Harness.NAME_FIELD);
    failedToFail();
  });

  it('pageShowsText fails when the page does not show it', () => {
    says('Expected the page to show "Goodbye", but it did not (waited 0.5 s).');
    Checks.pageShowsText('Goodbye');
    failedToFail();
  });

  it('titleIs fails on another title, quoting it', () => {
    says('Expected the page title "Other page", but it was "Harness page" (waited 0.5 s).');
    Checks.titleIs('Other page');
    failedToFail();
  });

  it('allShown fails naming the first element missing', () => {
    says('Expected the page to show the missing heading, but it did not (waited 0.5 s).');
    Checks.allShown('its headings', Harness.CONTACT_HEADING, Harness.MISSING_HEADING, Harness.HIDDEN_BUTTON);
    failedToFail();
  });

  it('The state checks pass what they should, and text with quotes is found as given', () => {
    Checks.pageShowsText('Say "hi"');
    Checks.hasCount('items', byCss('#items li'), 2);
    Checks.isEnabled(Harness.ADD_BUTTON);
    Checks.isDisabled(Harness.OFF_BUTTON);
    Checks.isNotChecked(Harness.AGREE_BOX);
    UserActions.tick(Harness.AGREE_BOX);
    Checks.isChecked(Harness.AGREE_BOX);
    Checks.hasAttribute(Harness.HELP_LINK, 'href', '/help');
    Checks.refusesEmpty(Harness.TOWN_FIELD);
  });

  it('hasCount fails on another number, saying how many it saw', () => {
    says('Expected the page to show 3 items, but it showed 2 (waited 0.5 s).');
    Checks.hasCount('items', byCss('#items li'), 3);
    failedToFail();
  });

  it('isEnabled fails on a disabled button', () => {
    says('Expected the off button to be enabled, but it was disabled (waited 0.5 s).');
    Checks.isEnabled(Harness.OFF_BUTTON);
    failedToFail();
  });

  it('isChecked fails on an empty box', () => {
    says('Expected the agree box to be checked, but it was not (waited 0.5 s).');
    Checks.isChecked(Harness.AGREE_BOX);
    failedToFail();
  });

  it('hasAttribute fails on another value, quoting it', () => {
    says(`Expected the help link's href to be "/about", but it was "/help" (waited 0.5 s).`);
    Checks.hasAttribute(Harness.HELP_LINK, 'href', '/about');
    failedToFail();
  });

  it('A failure is explained with its step and its reason', () => {
    cy.then(() => {
      StepLog.start();
    });
    UserActions.click(Harness.ADD_BUTTON);
    cy.then(() => {
      const explained = StepLog.failure(new Error('Timed out retrying after 500ms: Expected the hidden button to be shown, but it was not (waited 0.5 s).'));
      expect(explained).to.equal('   FAILED at step 1: Click the add button\n   because: Expected the hidden button to be shown, but it was not (waited 0.5 s).');
    });
  });

  it('A button far down a page that scrolls smoothly takes the click', () => {
    UserActions.click(Harness.FAR_BUTTON);
    Checks.hasText(Harness.FAR_TEXT, 'Clicked');
  });

  it('A cookie banner that shows after the page opened, over a button, is accepted, and the click goes through', () => {
    UserActions.click(Harness.SUMMON_BUTTON);
    UserActions.click(Harness.UNDER_BUTTON);
    Checks.hasText(Harness.UNDER_TEXT, 'Clicked');
  });

  it('A heading that fades in as it is scrolled to is found: the check scrolls to it, as a visitor would', () => {
    Checks.isShown(Harness.REVEALED_HEADING);
    Checks.hasText(Harness.REVEALED_HEADING, 'Revealed on scroll');
  });

  it('Actions do what their steps say, and the steps say it', () => {
    UserActions.click(Harness.ADD_BUTTON);
    UserActions.click(Harness.ADD_BUTTON);
    Checks.hasText(Harness.COUNT, '2');
    UserActions.type(Harness.NAME_FIELD, 'Ann');
    Checks.hasValue(Harness.NAME_FIELD, 'Ann');
    UserActions.clear(Harness.NAME_FIELD);
    Checks.hasValue(Harness.NAME_FIELD, '');
    UserActions.typeSecret(Harness.NAME_FIELD, 'hunter2');
    UserActions.tick(Harness.AGREE_BOX);
    cy.get('#agree').should('be.checked');
    UserActions.untick(Harness.AGREE_BOX);
    cy.get('#agree').should('not.be.checked');
    UserActions.choose(Harness.COLOUR_LIST, 'Blue');
    Checks.hasValue(Harness.COLOUR_LIST, 'Blue');
    UserActions.readText(Harness.SPACED_TEXT).then((read) => expect(read).to.equal('Hello world'));
    cy.then(() => {
      expect(StepLog.steps()).to.deep.equal([
        'Click the add button',
        'Click the add button',
        'Check that the count says "2"',
        'Type "Ann" into the name field',
        'Check that the name field holds "Ann"',
        'Clear the name field',
        'Check that the name field holds ""',
        'Type the secret into the name field',
        'Tick the agree box',
        'Untick the agree box',
        'Choose "Blue" in the colour list',
        'Check that the colour list holds "Blue"',
        'Read the spaced text: "Hello world"',
      ]);
      expect(StepLog.steps().some((step) => step.includes('hunter2')), 'A secret must never be logged').to.equal(false);
    });
  });
});
